<body>
<h1>Maze Discovery — 24 Autonomous Bots</h1>
<div class="panel">
  <div class="stat">Completed: <b id="completed">0/24</b></div>
  <div class="stat">Ticks: <b id="timer">0</b></div>
  <button id="reset">New Maze</button>
</div>
<div id="maze"><canvas id="canvas"></canvas></div>
<div class="legend">
  <span><span class="dot" style="background:#4caf50"></span>Spawn</span>
  <span><span class="dot" style="background:#f44336"></span>Exit</span>
</div>

<script>
(function () {
  "use strict";

  // ---------- Seeded RNG ----------
  function mulberry32(seed) {
    let a = seed >>> 0;
    return function () {
      a = (a + 0x6D2B79F5) | 0;
      let t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  function shuffle(arr, rng) {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(rng() * (i + 1));
      const tmp = arr[i]; arr[i] = arr[j]; arr[j] = tmp;
    }
    return arr;
  }

  function allPermutations(arr) {
    if (arr.length <= 1) return [arr.slice()];
    const result = [];
    for (let i = 0; i < arr.length; i++) {
      const rest = arr.slice(0, i).concat(arr.slice(i + 1));
      const subPerms = allPermutations(rest);
      for (const p of subPerms) result.push([arr[i]].concat(p));
    }
    return result;
  }

  // ---------- Maze generation (randomized DFS / recursive backtracker) ----------
  const ROWS = 21, COLS = 21, CELL = 20;
  const DIR_LIST = ['n', 'e', 's', 'w'];
  const DIR_DELTA = {
    n: { dr: -1, dc: 0, opp: 's' },
    s: { dr: 1, dc: 0, opp: 'n' },
    e: { dr: 0, dc: 1, opp: 'w' },
    w: { dr: 0, dc: -1, opp: 'e' }
  };

  function key(r, c) { return r + ',' + c; }

  function generateMaze(rows, cols, rng) {
    const grid = [];
    for (let r = 0; r < rows; r++) {
      const row = [];
      for (let c = 0; c < cols; c++) {
        row.push({ n: true, e: true, s: true, w: true, visited: false });
      }
      grid.push(row);
    }
    const stack = [{ r: 0, c: 0 }];
    grid[0][0].visited = true;
    while (stack.length) {
      const cur = stack[stack.length - 1];
      const order = shuffle(DIR_LIST.slice(), rng);
      let moved = false;
      for (const dir of order) {
        const d = DIR_DELTA[dir];
        const nr = cur.r + d.dr, nc = cur.c + d.dc;
        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && !grid[nr][nc].visited) {
          grid[cur.r][cur.c][dir] = false;
          grid[nr][nc][d.opp] = false;
          grid[nr][nc].visited = true;
          stack.push({ r: nr, c: nc });
          moved = true;
          break;
        }
      }
      if (!moved) stack.pop();
    }
    return grid;
  }

  function bfsFarthest(grid, rows, cols, start) {
    const dist = Array.from({ length: rows }, () => new Array(cols).fill(-1));
    dist[start.r][start.c] = 0;
    const queue = [start];
    let far = start;
    let head = 0;
    while (head < queue.length) {
      const cur = queue[head++];
      const w = grid[cur.r][cur.c];
      const neighbors = [];
      if (!w.n) neighbors.push({ r: cur.r - 1, c: cur.c });
      if (!w.s) neighbors.push({ r: cur.r + 1, c: cur.c });
      if (!w.e) neighbors.push({ r: cur.r, c: cur.c + 1 });
      if (!w.w) neighbors.push({ r: cur.r, c: cur.c - 1 });
      for (const n of neighbors) {
        if (dist[n.r][n.c] === -1) {
          dist[n.r][n.c] = dist[cur.r][cur.c] + 1;
          if (dist[n.r][n.c] > dist[far.r][far.c]) far = n;
          queue.push(n);
        }
      }
    }
    return far;
  }

  // ---------- Game state ----------
  let grid, spawn, exit, bots, elapsedInternal, finishedAll, currentSeed;
  let autoPlay = true;
  const TICK_MS = 70;
  let lastTickTime = 0;

  function neighborCoord(r, c, dir) {
    const d = DIR_DELTA[dir];
    return { r: r + d.dr, c: c + d.dc };
  }

  function makeBot(id, prefOrder, start) {
    return {
      id: id,
      color: 'hsl(' + Math.round(id * (360 / 24)) + ',75%,58%)',
      pos: { r: start.r, c: start.c },
      prevPos: { r: start.r, c: start.c },
      r: start.r, c: start.c,
      stack: [{ r: start.r, c: start.c }],
      visitedSet: new Set([key(start.r, start.c)]),
      deadEndSet: new Set(),
      deadEnds: [],
      path: [{ r: start.r, c: start.c }],
      prefOrder: prefOrder,
      finished: false,
      finishTick: null
    };
  }

  function stepBot(bot, tickNum) {
    if (bot.finished) return;
    const cur = bot.stack[bot.stack.length - 1];
    const w = grid[cur.r][cur.c];
    let newPos = null;

    for (const dir of bot.prefOrder) {
      if (w[dir]) continue; // wall blocks this direction
      const n = neighborCoord(cur.r, cur.c, dir);
      const k = key(n.r, n.c);
      if (!bot.visitedSet.has(k)) {
        bot.visitedSet.add(k);
        bot.stack.push(n);
        newPos = n;
        break;
      }
    }

    if (!newPos) {
      // dead end (or fully explored branch) -> backtrack
      const k = key(cur.r, cur.c);
      if (!bot.deadEndSet.has(k)) {
        bot.deadEndSet.add(k);
        bot.deadEnds.push({ r: cur.r, c: cur.c });
      }
      if (bot.stack.length > 1) {
        bot.stack.pop();
        newPos = bot.stack[bot.stack.length - 1];
      } else {
        newPos = cur; // fully stuck (should not happen in a connected maze)
      }
    }

    bot.prevPos = { r: cur.r, c: cur.c };
    bot.pos = { r: newPos.r, c: newPos.c };
    bot.r = newPos.r; bot.c = newPos.c;
    bot.path.push({ r: newPos.r, c: newPos.c });

    if (newPos.r === exit.r && newPos.c === exit.c) {
      bot.finished = true;
      bot.finishTick = tickNum;
    }
  }

  function doTick() {
    if (finishedAll) return;
    elapsedInternal++;
    for (const bot of bots) stepBot(bot, elapsedInternal);
    lastTickTime = nowMs();
    if (bots.every(b => b.finished)) finishedAll = true;
    window.game.elapsed = elapsedInternal;
  }

  function nowMs() {
    return (typeof performance !== 'undefined' && performance.now) ? performance.now() : 0;
  }

  function resetGame(seedInput) {
    const explicitSeed = (typeof seedInput === 'number' && isFinite(seedInput));
    const seed = explicitSeed ? (seedInput >>> 0) : ((Math.floor(Math.random() * 0xFFFFFFFF)) >>> 0);
    currentSeed = seed;
    const rng = mulberry32(seed);

    grid = generateMaze(ROWS, COLS, rng);
    spawn = { r: 0, c: 0 };
    exit = bfsFarthest(grid, ROWS, COLS, spawn);

    const perms = shuffle(allPermutations(DIR_LIST), rng);
    bots = [];
    for (let i = 0; i < 24; i++) {
      bots.push(makeBot(i, perms[i % perms.length], spawn));
    }

    elapsedInternal = 0;
    finishedAll = false;
    lastTickTime = nowMs();

    // Explicit numeric seed => treat as programmatic/test control, disable autoplay
    // so external tick() calls remain fully deterministic.
    autoPlay = !explicitSeed;

    syncGameObject();
    updateStatsUI();
  }

  function tickN(n) {
    n = (typeof n === 'number' && n > 0) ? Math.floor(n) : 1;
    for (let i = 0; i < n; i++) doTick();
    updateStatsUI();
  }

  function syncGameObject() {
    window.game.size = { rows: ROWS, cols: COLS };
    window.game.spawn = { r: spawn.r, c: spawn.c };
    window.game.exit = { r: exit.r, c: exit.c };
    window.game.bots = bots;
    window.game.elapsed = elapsedInternal;
  }

  window.game = {
    tick: tickN,
    reset: resetGame,
    walls: function (r, c) {
      const cell = grid[r][c];
      return { n: cell.n, e: cell.e, s: cell.s, w: cell.w };
    },
    elapsed: 0,
    size: { rows: ROWS, cols: COLS },
    spawn: { r: 0, c: 0 },
    exit: { r: 0, c: 0 },
    bots: []
  };

  // ---------- Rendering ----------
  const canvas = document.getElementById('canvas');
  const ctx = canvas.getContext('2d');
  canvas.width = COLS * CELL;
  canvas.height = ROWS * CELL;

  function lerp(a, b, t) { return a + (b - a) * t; }

  function drawMaze() {
    ctx.strokeStyle = '#4a5468';
    ctx.lineWidth = 2;
    ctx.lineCap = 'square';
    ctx.beginPath();
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        const cell = grid[r][c];
        const x = c * CELL, y = r * CELL;
        if (cell.n) { ctx.moveTo(x, y); ctx.lineTo(x + CELL, y); }
        if (cell.s) { ctx.moveTo(x, y + CELL); ctx.lineTo(x + CELL, y + CELL); }
        if (cell.w) { ctx.moveTo(x, y); ctx.lineTo(x, y + CELL); }
        if (cell.e) { ctx.moveTo(x + CELL, y); ctx.lineTo(x + CELL, y + CELL); }
      }
    }
    ctx.stroke();
  }

  function drawMarker(cell, color) {
    const pad = CELL * 0.22;
    ctx.fillStyle = color;
    ctx.fillRect(cell.c * CELL + pad, cell.r * CELL + pad, CELL - pad * 2, CELL - pad * 2);
  }

  function drawFrame() {
    let t = (nowMs() - lastTickTime) / TICK_MS;
    if (t > 1) t = 1; if (t < 0) t = 0;

    ctx.fillStyle = '#10121a';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    drawMaze();
    drawMarker(spawn, '#4caf50');
    drawMarker(exit, '#f44336');

    for (const bot of bots) {
      const px = lerp(bot.prevPos.c, bot.pos.c, t) * CELL + CELL / 2;
      const py = lerp(bot.prevPos.r, bot.pos.r, t) * CELL + CELL / 2;
      ctx.beginPath();
      ctx.fillStyle = bot.color;
      ctx.arc(px, py, Math.max(2.5, CELL * 0.26), 0, Math.PI * 2);
      ctx.fill();
      if (bot.finished) {
        ctx.lineWidth = 1;
        ctx.strokeStyle = '#fff';
        ctx.stroke();
      }
    }

    requestAnimationFrame(drawFrame);
  }

  function updateStatsUI() {
    const completedEl = document.getElementById('completed');
    const timerEl = document.getElementById('timer');
    const done = bots.reduce((acc, b) => acc + (b.finished ? 1 : 0), 0);
    completedEl.textContent = done + '/24';
    timerEl.textContent = String(elapsedInternal);
  }

  function autoPlayLoop() {
    if (autoPlay && !finishedAll) {
      doTick();
      updateStatsUI();
    }
    setTimeout(autoPlayLoop, TICK_MS);
  }

  document.getElementById('reset').addEventListener('click', function () {
    resetGame();
  });

  // ---------- Boot ----------
  resetGame();
  requestAnimationFrame(drawFrame);
  autoPlayLoop();
})();
</script>
</body>
</html>
